#!/usr/bin/env bash
# Render supplies native source identity; the private key is generated by
# the reviewed Blueprint, never copied from Hugging Face or GitHub.
set -euo pipefail
export SSL_CERT_FILE="$PWD/.ci/trust/cacert.pem"
export GMA_APPLICATION_COMMIT="${RENDER_GIT_COMMIT:?Render source commit is required}"
exec .venv/bin/python -m uvicorn global_medicines_atlas.hosted_service:create_app \
  --factory --host 0.0.0.0 --port "${PORT:-10000}"
